"""Graded reading texts generated by the lesson LLM and validated by coverage (contract C10).

Open A2-C1 graded readers were not found, so texts are generated from the
learner's known words and checked against their FSRS state. A text that misses
the coverage target is regenerated at most twice; the best draft is returned.
"""

from __future__ import annotations

import asyncio
from pathlib import Path

from deeptutor.utils.json_parser import parse_json_response

from .coverage import coverage, known_forms
from .text import NAMES, UNSPACED

BANDS = ("A1", "A2", "B1", "B2", "C1", "C2")
MAX_REGENERATIONS = 2
# Enough vocabulary to write from without an oversized prompt.
KNOWN_IN_PROMPT = 400
AVOID_IN_PROMPT = 40

SYSTEM_PROMPT = (
    "You write graded reading texts for one adult language learner. "
    "Reply with a single JSON object and nothing else."
)


class GradedTextError(RuntimeError):
    """The model returned no usable text."""


def _prompt(
    lang: str, band: str, topic: str | None, known: set[str], target: float, avoid: list[str]
) -> str:
    name = NAMES[lang]
    question_language = name if band >= "B1" else "English"
    lines = [
        f"Write a CEFR {band} reading text in {name}"
        + (f" about: {topic}." if topic else " on an everyday topic."),
        "Keep it to 6-12 sentences, each natural and complete.",
    ]
    if known:
        vocabulary = ", ".join(sorted(known)[:KNOWN_IN_PROMPT])
        lines += [
            f"At least {target:.0%} of the running words must be from this list of word forms "
            "the learner knows, used exactly as written (other inflections count as unknown):",
            vocabulary,
        ]
    else:
        lines.append("The learner knows few words yet: use only the most frequent, simplest words.")
    if avoid:
        lines.append("A previous draft used these unknown words; avoid them: " + ", ".join(avoid))
    lines += [
        f"Then write 3 short comprehension questions with short answers, in {question_language}.",
        'JSON shape: {"sentences": ["..."], "questions": [{"q": "...", "a": "..."}]}',
    ]
    return "\n".join(lines)


def _parse(raw: str, lang: str) -> dict | None:
    data = parse_json_response(raw, fallback=None)
    if not isinstance(data, dict):
        return None
    sentences = [s.strip() for s in data.get("sentences") or [] if isinstance(s, str) and s.strip()]
    questions = [
        {"q": item["q"].strip(), "a": item["a"].strip()}
        for item in data.get("questions") or []
        if isinstance(item, dict)
        and isinstance(item.get("q"), str)
        and isinstance(item.get("a"), str)
        and item["q"].strip()
        and item["a"].strip()
    ]
    if not sentences or not questions:
        return None
    text = ("" if lang in UNSPACED else " ").join(sentences)
    return {"text": text, "sentences": sentences, "questions": questions}


async def graded_text(
    db_path: Path, lang: str, band: str, topic: str | None, target_coverage: float
) -> dict:
    from deeptutor.services.llm import complete

    known = await asyncio.to_thread(known_forms, db_path, lang)
    best: dict | None = None
    avoid: list[str] = []
    for _ in range(1 + MAX_REGENERATIONS):
        raw = await complete(
            prompt=_prompt(lang, band, topic, known, target_coverage, avoid),
            system_prompt=SYSTEM_PROMPT,
            temperature=0.7,
            max_tokens=2000,
        )
        draft = _parse(raw, lang)
        if draft is None:
            continue
        measured = await asyncio.to_thread(coverage, lang, draft["text"], known)
        draft.update(coverage=measured["coverage"], unknown=measured["unknown"])
        if best is None or draft["coverage"] > best["coverage"]:
            best = draft
        if draft["coverage"] >= target_coverage:
            break
        avoid = measured["unknown"][:AVOID_IN_PROMPT]
    if best is None:
        raise GradedTextError("The model returned no usable graded text")
    return best
